#include <stdio.h>

void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

int main(void) {
    int x = 3;
    int y = 8;
    printf("Before: x=%d, y=%d\n", x, y);
    swap(&x, &y);
    printf("After:  x=%d, y=%d\n", x, y);
    swap(&x, &y);
    printf("Back:   x=%d, y=%d\n", x, y);
    return 0;
}

#include <stdio.h>

long factorial(int n) {
    if (n <= 1) {
        return 1;
    }
    return n * factorial(n - 1);
}

int main(void) {
    printf("Factorial table from 0 to 10:\n");
    for (int i = 0; i <= 10; i++) {
        long result = factorial(i);
        printf("%d! = %ld\n", i, result);
    }
    return 0;
}

