void fizzbuzz(int limit, int *fizz_count, int *buzz_count) {
    for (int number = 1; number <= limit; number++) {
        if (number % 15 == 0) {
            printf("FizzBuzz\n");
            (*fizz_count)++;
            (*buzz_count)++;
        } else if (number % 3 == 0) {
            printf("Fizz\n");
            (*fizz_count)++;
        } else if (number % 5 == 0) {
            printf("Buzz\n");
            (*buzz_count)++;
        } else {
            printf("%d\n", number);
        }
    }
}

int main(void) {
    int fizz = 0;
    int buzz = 0;
    fizzbuzz(100, &fizz, &buzz);
    printf("Fizz: %d, Buzz: %d\n", fizz, buzz);
    return 0;
}

#include <stdio.h>

struct Student {
    char name[30];
    int grades[5];
};

double average(const struct Student *student) {
    int total = 0;
    for (int i = 0; i < 5; i++) {
        total += student->grades[i];
    }
    return total / 5.0;
}

int main(void) {
    struct Student students[3] = {
        {"Ada", {15, 18, 12, 19, 14}},
        {"Bob", {9, 11, 13, 10, 12}},
        {"Eve", {17, 16, 18, 20, 15}}
    };
    double total = 0.0;
    for (int i = 0; i < 3; i++) {
        double avg = average(&students[i]);
        printf("%s: %.1f/20\n", students[i].name, avg);
        total += avg;
    }
    printf("Class average: %.1f/20\n", total / 3);
    return 0;
}

#include <stdio.h>

int string_length(const char *text) {
    int length = 0;
    while (text[length] != '\0') {
        length++;
    }
    return length;
}

void reverse(char *text) {
    int length = string_length(text);
    for (int i = 0; i < length / 2; i++) {
        char temp = text[i];
        text[i] = text[length - 1 - i];
        text[length - 1 - i] = temp;
    }
}

int is_palindrome(const char *text) {
    int length = string_length(text);
    for (int i = 0; i < length / 2; i++) {
        if (text[i] != text[length - 1 - i]) {
            return 0;
        }
    }
    return 1;
}

int main(void) {
    char word[] = "dactylo";
    printf("Before: %s\n", word);
    reverse(word);
    printf("After:  %s\n", word);
    printf("Palindrome: %s\n", is_palindrome("kayak") ? "yes" : "no");
    return 0;
}

#include <stdio.h>

int is_prime(int n) {
    if (n < 2) {
        return 0;
    }
    for (int divisor = 2; divisor * divisor <= n; divisor++) {
        if (n % divisor == 0) {
            return 0;
        }
    }
    return 1;
}

int next_prime(int start) {
    int candidate = start + 1;
    while (!is_prime(candidate)) {
        candidate++;
    }
    return candidate;
}

int main(void) {
    int count = 0;
    for (int candidate = 2; candidate < 100; candidate++) {
        if (is_prime(candidate)) {
            printf("%4d", candidate);
            count++;
            if (count % 8 == 0) {
                printf("\n");
            }
        }
    }
    printf("\nFound %d primes below 100.\n", count);
    printf("First prime after 100: %d\n", next_prime(100));
    return 0;
}

