#include <stdio.h>

int is_vowel(char c) {
    return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u' || c == 'y';
}

int count_vowels(const char *text) {
    int count = 0;
    for (int i = 0; text[i] != '\0'; i++) {
        if (is_vowel(text[i])) {
            count++;
        }
    }
    return count;
}

int count_consonants(const char *text) {
    int count = 0;
    for (int i = 0; text[i] != '\0'; i++) {
        char c = text[i];
        if (c >= 'a' && c <= 'z' && !is_vowel(c)) {
            count++;
        }
    }
    return count;
}

int main(void) {
    char sentence[] = "programming is a superpower";
    printf("\"%s\"\n", sentence);
    printf("Vowels: %d\n", count_vowels(sentence));
    printf("Consonants: %d\n", count_consonants(sentence));
    return 0;
}

#include <stdio.h>

double compute(double a, double b, char op) {
    switch (op) {
    case '+':
        return a + b;
    case '-':
        return a - b;
    case '*':
        return a * b;
    case '/':
        if (b == 0.0) {
            printf("Error: division by zero\n");
            return 0.0;
        }
        return a / b;
    default:
        printf("Unknown operator %c\n", op);
        return 0.0;
    }
}

int main(void) {
    double left[] = {12.0, 7.5, 100.0, 9.0};
    double right[] = {3.0, 2.5, 4.0, 0.0};
    char ops[] = {'+', '*', '/', '/'};
    for (int i = 0; i < 4; i++) {
        double result = compute(left[i], right[i], ops[i]);
        printf("%.1f %c %.1f = %.2f\n", left[i], ops[i], right[i], result);
    }
    return 0;
}
